/* Hybrid: compact editorial feature and a task-oriented discovery library. */
window.Concepts.C = {
  home(H,s){
    const main=H.get('localsend');
    return `${H.header('hybrid')}<main id="main" class="c-main" tabindex="-1"><div class="c-container">
      <section class="c-opening" aria-labelledby="c-home-title">
        <div class="c-opening-copy"><p class="eyebrow">MỘT THƯ VIỆN. NHIỀU ĐIỀU CÓ ÍCH.</p><h1 id="c-home-title">Công cụ hay.<br>Đúng lúc bạn cần.</h1><p>Tìm tài nguyên để học tốt hơn, làm nhẹ hơn<br>và bắt đầu một điều mới.</p>${H.search('','c-home-search','Bạn muốn làm gì hôm nay?')}<div class="c-trending"><span>Thử tìm</span><a href="${H.url('discover',{q:'chuyển tệp'})}">Chuyển tệp</a><a href="${H.url('discover',{q:'sơ đồ'})}">Vẽ sơ đồ</a><a href="${H.url('discover',{category:'Học tập'})}">Tự học</a></div></div>
        <article class="c-feature"><div class="c-feature-top"><span class="eyebrow">GỌN MỘT VIỆC MỖI NGÀY</span><span class="c-feature-number">01 / Bộ chọn mẫu</span></div><div class="c-feature-media">${H.preview(main)}</div><div class="c-feature-bottom">${H.icon(main,'sm')}<div><h2>Chuyển tệp. Không lòng vòng.</h2><p>LocalSend · khám phá cách kết nối các thiết bị.</p></div><a class="icon-button" href="${H.url('detail/localsend')}" aria-label="Khám phá LocalSend">${H.symbol('arrow')}</a></div></article>
      </section>
      <nav class="c-task-nav" aria-label="Tìm theo nhu cầu">${[['work','Văn phòng','Làm việc gọn hơn'],['book','Học tập','Học thêm điều mới'],['spark','Sáng tạo','Thỏa sức sáng tạo'],['code','Lập trình','Khám phá mã nguồn'],['bookmark','Bảo mật','Chăm sóc dữ liệu'],['grid','Giải trí','Nghỉ ngơi một chút']].map(([icon,category,label])=>`<a href="${H.url('discover',{category})}">${H.symbol(icon)}<span>${label}</span>${H.symbol('chevron')}</a>`).join('')}</nav>
      <section class="c-featured-shelf">${H.sectionHead('Nhỏ gọn. Nhưng làm được việc.','Một vài điểm bắt đầu cho thư viện của bạn.',H.url('discover'))}<div class="c-quick-grid">${H.pick(['excalidraw','obs','libreoffice','keepassxc']).map(r=>H.card(r,{compact:true})).join('')}</div></section>
      <section class="c-library" aria-labelledby="c-library-title"><div class="c-library-heading"><div><p class="eyebrow">KHÁM PHÁ THƯ VIỆN</p><h2 id="c-library-title">Chọn đúng việc.<br>Gặp đúng công cụ.</h2></div><a class="text-link" href="${H.url('discover')}">Mở toàn bộ catalog ${H.symbol('arrow')}</a></div><div class="c-discovery-tabs" role="group" aria-label="Nhóm tài nguyên xem nhanh"><button type="button" data-quick="all" aria-pressed="true">Tất cả</button><button type="button" data-quick="rating" aria-pressed="false">Điểm cao · mẫu</button><button type="button" data-quick="repo" aria-pressed="false">Repo GitHub</button><button type="button" data-quick="learn" aria-pressed="false">Học tập</button><button type="button" data-quick="office" aria-pressed="false">Văn phòng</button></div><div id="quick-results" class="c-index-grid" aria-live="polite">${H.pick(['localsend','excalidraw','godot','anki','powertoys','phet']).map(r=>H.row(r)).join('')}</div><p class="c-trust-note">Nhóm “Điểm cao” sử dụng phiếu mẫu để review UI; chưa có đánh giá cộng đồng thật.</p></section>
      <section class="c-learning-feature"><div class="c-learning-copy"><p class="eyebrow">DÀNH CHỖ CHO ĐIỀU MUỐN HỌC</p><h2>Một ý tưởng nhỏ.<br>Một thế giới mới.</h2><p>Học bằng cách thử làm. Khám phá Godot và những tài nguyên để bắt đầu hành trình tạo trò chơi.</p><a class="button" href="${H.url('detail/godot')}">Khám phá Godot ${H.symbol('arrow')}</a><a class="text-link" href="${H.url('discover',{kind:'repo'})}">Thêm repo để khám phá ${H.symbol('code')}</a></div><div class="c-learning-media">${H.preview(H.get('godot'))}</div></section>
      <section class="c-learning-shelf">${H.sectionHead('Tài nguyên học tập, mở ra miễn phí.','Tìm một cách học phù hợp với bạn. Điều kiện từng nguồn cần được kiểm lại.',H.url('discover',{kind:'learn',price:'Miễn phí'}))}<div class="c-learning-grid">${H.pick(['phet','freecodecamp','mdn']).map(r=>H.card(r)).join('')}</div></section>
      <section class="c-office-shelf">${H.sectionHead('Những việc nhỏ ở bàn làm việc.','Tài liệu, tệp tin và quy trình rõ ràng hơn.',H.url('discover',{category:'Văn phòng'}))}<div class="c-office-grid">${H.pick(['drawio','libreoffice','powertoys']).map(r=>H.row(r)).join('')}</div></section>
      <section class="c-collections">${H.sectionHead('Đã chọn cùng nhau. Dùng cùng nhau.','Bộ sưu tập minh họa theo một công việc trọn vẹn.')}${H.collections()}</section>
      <section class="c-contribute"><div>${H.symbol('plus')}<div><h2>Thêm một điều hữu ích vào thư viện.</h2><p>Bạn có công cụ muốn chia sẻ? Bắt đầu bằng một đường dẫn.</p></div></div><button type="button" class="button secondary" data-open="contribute">Đề xuất tài nguyên ${H.symbol('arrow')}</button></section>
    </div></main>${H.footer()}`;
  },
  discover(H,s){
    const view=s.params.get('view')==='list'?'list':'grid',params=Object.fromEntries(s.params);
    return `${H.header('hybrid')}<main id="main" class="c-main" tabindex="-1"><div class="c-container c-discover"><section class="c-discover-opening"><div><p class="eyebrow">TÌM THEO CÁCH CỦA BẠN</p><h1>Một thư viện, nhiều khả năng.</h1><p>Gõ điều muốn làm. Thu gọn theo nền tảng và nhu cầu.</p></div>${H.search(s.query,'c-discover-search','Tìm tên, công dụng hoặc chủ đề…')}</section><div class="c-discover-layout"><aside class="c-filter-rail"><details open><summary>${H.symbol('filter')} Thu gọn lựa chọn</summary>${H.filters(s)}</details><p>Miễn phí và mã nguồn mở là hai điều khác nhau. Xem điều khoản cụ thể trong hồ sơ tài nguyên.</p></aside><section class="c-discover-results" aria-label="Kết quả tìm kiếm"><div class="c-result-controls">${H.resultsHead(s)}<div class="c-view-controls" role="group" aria-label="Cách xem kết quả"><a class="icon-button ${view==='grid'?'active':''}" href="${H.url('discover',{...params,view:'grid'})}" aria-label="Xem dạng lưới" ${view==='grid'?'aria-current="true"':''}>${H.symbol('grid')}</a><a class="icon-button ${view==='list'?'active':''}" href="${H.url('discover',{...params,view:'list'})}" aria-label="Xem dạng danh sách" ${view==='list'?'aria-current="true"':''}>${H.symbol('list')}</a></div></div>${s.filtered.length?`<div class="${view==='list'?'c-result-list':'c-result-grid'}">${s.filtered.map(r=>view==='list'?H.row(r):H.card(r)).join('')}</div>`:H.empty(s)}</section></div></div></main>${H.footer()}`;
  },
  detail(H,r,s){return `${H.header('hybrid')}<main id="main" class="c-main" tabindex="-1"><div class="c-container c-detail"><nav class="c-breadcrumb" aria-label="Đường dẫn"><a href="${H.url('discover')}">Thư viện</a><span>/</span><a href="${H.url('discover',{category:r.category})}">${H.escape(r.category)}</a><span>/</span><span>${H.escape(r.name)}</span></nav><section class="c-detail-header"><div class="c-detail-identity">${H.icon(r,'lg')}<div><p class="eyebrow">HỒ SƠ TÀI NGUYÊN · MINH HỌA</p><h1>${H.escape(r.name)}</h1><p>${H.escape(r.summary)}</p></div></div><div class="c-detail-cta"><a class="button" href="${r.homepage}" target="_blank" rel="noopener noreferrer">Đến trang chính thức ${H.symbol('external')}</a><button class="button secondary" type="button" data-save="${r.id}">${H.symbol('bookmark')} Lưu trong phiên</button></div></section><div class="c-detail-overview"><div class="c-detail-preview">${H.preview(r)}</div><aside class="c-detail-facts"><h2>Nhìn nhanh trước khi thử.</h2>${H.facts(r)}</aside></div><div class="c-detail-reading"><nav aria-label="Nội dung hồ sơ"><p class="eyebrow">TRONG HỒ SƠ NÀY</p><a href="${H.url('detail/'+r.id)}" data-scroll="overview">Công dụng & cách bắt đầu</a><a href="${H.url('detail/'+r.id)}" data-scroll="source">Nguồn & điều cần biết</a><a href="${H.url('credits')}">Nguồn hình ảnh</a></nav><article id="detail-overview">${H.article(r)}</article></div>${H.related(r)}</div></main>${H.footer()}`;}
};
